//! Assembles the README from the generated images.

use crate::github::Cache;
use crate::svg::esc;

use super::Image;

pub struct Inputs<'a> {
    pub cache: &'a Cache,
    pub images: &'a super::Images,
}

pub fn render(input: &Inputs<'_>) -> String {
    let mut out = String::new();

    out.push_str(&format!(
        "<!--\n  GENERATED by `cargo run --release`. Do not edit by hand.\n  Edit profile.config.json and regenerate:\n      cargo run --release              # refresh GitHub data + rebuild\n      cargo run --release -- generate  # rebuild from assets/profile.json\n  Last data sync: {}\n-->\n\n",
        input.cache.generated_at.as_deref().unwrap_or("never")
    ));

    // Identity, then the pulse, then the story.
    out.push_str(&block(&input.images.hero));
    out.push('\n');
    out.push_str(&block(&input.images.ticker));
    out.push('\n');
    out.push_str(&block(&input.images.about));
    out.push('\n');

    // Projects.
    out.push_str("<p align=\"center\">\n");
    out.push_str(&img(&input.images.target_header, None));
    out.push_str("<br>\n");
    for image in &input.images.targets {
        out.push_str(&img(image, image.href.as_deref()));
        out.push_str("<br>\n");
    }
    out.push_str("</p>\n");

    // Signals.
    if let Some(header) = &input.images.signal_header {
        out.push_str("\n<p align=\"center\">\n");
        out.push_str(&img(header, None));
        out.push_str("<br>\n");
        for image in &input.images.signals {
            out.push_str(&img(image, image.href.as_deref()));
            out.push_str("<br>\n");
        }
        out.push_str("</p>\n");
    }

    // Contact.
    out.push_str("\n<p align=\"center\">\n");
    out.push_str(&img(&input.images.contact_header, None));
    out.push_str("<br>\n");
    for image in &input.images.contacts {
        out.push_str(&img(image, image.href.as_deref()));
        out.push('\n');
    }
    out.push_str("</p>\n");

    out
}

fn block(image: &Image) -> String {
    format!(
        "<p align=\"center\"><img src=\"{}\" width=\"100%\" alt=\"{}\" /></p>\n",
        esc(&image.file),
        esc(&image.alt)
    )
}

fn img(image: &Image, href: Option<&str>) -> String {
    let size = match image.height {
        Some(h) => format!(" height=\"{h:.0}\""),
        None => " width=\"100%\"".to_string(),
    };
    let tag = format!(
        "<img src=\"{}\"{} alt=\"{}\" />",
        esc(&image.file),
        size,
        esc(&image.alt)
    );
    match href.filter(|h| !h.trim().is_empty()) {
        Some(url) => format!("<a href=\"{}\">{tag}</a>", esc(url)),
        None => tag,
    }
}
